<script setup>
import { computed, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import FinanceTable from '../components/FinanceTable.vue'
import FinanceDialog from '../components/FinanceDialog.vue'
import { context, data, dbState, engine, perform, attach, getFile } from '../finance/store'
import { CATEGORIES, NAV, ROLES } from '../finance/seed'
import { TYPES, STATUS } from '../finance/engine'
import { cents, convert, format, sum, proportional } from '../finance/money'
import { exportCsv, parseCsv } from '../finance/csv'
import historic from '../data/seed.json'
const route=useRoute();const router=useRouter()
const moduleId=computed(()=>route.meta.module||'home');const pageId=computed(()=>route.meta.page||'home')
const module=computed(()=>NAV.find(n=>n.id===moduleId.value)||NAV[0])
const title=computed(()=>module.value.pages?.find(([id])=>id===pageId.value)?.[1]||'财务工作台')
const executionDate=ref('');
const reportTab=ref('balance');const categoryDetail=ref('');const tableFilter=ref('all');const selectedId=ref('');const selectedKind=ref('document');const detailTab=ref('明细')
const modal=ref('');const formType=ref('');const form=reactive({});const lineInputs=ref([]);const allocationInputs=ref([]);const importRows=ref([]);const importFile=ref('');const matchMovement=ref('');const matchAmount=ref('');const detailNote=ref('');const accountFilter=ref(route.query.account||'');const manualLines=ref([])
const partyName=id=>data.parties.find(p=>p.id===id)?.name||id||'—'
const vesselName=id=>data.vessels.find(v=>v.id===id)?.name||'MSTS 本部'
const categoryName=id=>CATEGORIES.find(c=>c.id===id)?.name||id||'—'
const kindLabel=id=>({asset:'资产',contraAsset:'资产抵减',liability:'负债',equity:'权益',income:'收入',expense:'费用',management:'管理公司',vessel:'单船公司'}[id]||id)
const cashFlowLabel=id=>({operating:'经营活动',investing:'投资活动',financing:'筹资活动',internal:'内部划拨'}[id]||id)
const companyName=id=>data.companies.find(c=>c.id===id)?.name||id
const can=right=>engine.access(right)
const docs=computed(()=>engine.scoped(data.documents,{allPeriods:true}).filter(d=>d.date<=endDate.value&&(d.date.slice(0,7)===context.period||d.executionDate?.slice(0,7)===context.period||d.status==='approved'&&['payment','receipt','loan','loanReturn','transfer','cashSpend','funding','instrument'].includes(d.type))))
const endDate=computed(()=>new Date(Date.UTC(Number(context.period.slice(0,4)),Number(context.period.slice(5,7)),0)).toISOString().slice(0,10))
const asOfDocs=computed(()=>engine.scoped(data.documents,{allPeriods:true}).filter(d=>d.date<=endDate.value))
const arDocs=computed(()=>asOfDocs.value.filter(d=>d.type==='bill'&&['approved','executed'].includes(d.status)))
const apDocs=computed(()=>asOfDocs.value.filter(d=>['invoice','reimbursement','asset'].includes(d.type)&&['approved','executed'].includes(d.status)))
const arTotal=computed(()=>arDocs.value.reduce((n,d)=>n+convert(engine.outstanding(d,endDate.value),d.rate),0))
const apTotal=computed(()=>apDocs.value.reduce((n,d)=>n+convert(engine.outstanding(d,endDate.value),d.rate),0))
const accounts=computed(()=>engine.scoped(data.accounts,{allPeriods:true}))
const funds=computed(()=>accounts.value.filter(a=>a.currency==='USD').reduce((n,a)=>n+engine.balance(a.id,endDate.value),0))
const journals=computed(()=>engine.scoped(data.journals))
const reports=computed(()=>engine.reports())
const detailDoc=computed(()=>selectedKind.value==='journal'?data.journals.find(j=>j.id===selectedId.value):selectedKind.value==='movement'?data.movements.find(m=>m.id===selectedId.value):data.documents.find(d=>d.id===selectedId.value))
const detailAttachments=computed(()=>data.attachments.filter(a=>a.entityId===selectedId.value))
const relatedJournals=computed(()=>data.journals.filter(j=>(j.sourceId===selectedId.value||j.id===selectedId.value)&&engine.role().companies.includes(j.companyId)))
const relatedAllocations=computed(()=>data.allocations.filter(a=>a.docId===selectedId.value||a.sourceId===selectedId.value))
const relatedDocuments=computed(()=>data.documents.filter(d=>engine.role().companies.includes(d.companyId)&&d.id!==selectedId.value&&(data.allocations.some(a=>(a.docId===selectedId.value&&a.sourceId===d.id)||(a.sourceId===selectedId.value&&a.docId===d.id))||d.sourceId===selectedId.value||detailDoc.value?.sourceId===d.id||d.lines?.some(l=>l.sourceId===selectedId.value)||detailDoc.value?.lines?.some(l=>l.sourceId===d.id))))
const logs=computed(()=>data.audit.filter(a=>a.entityId===selectedId.value))
const notes={
 gl:'业务审核生成凭证草稿，审核过账后进入正式账簿和报表。', ar:'固定管理费与实际可收费用分别形成账单；运营拨款另记资金往来。', ap:'原票抬头、受益船、实际付款主体分别保留，余额由有效核销计算。', treasury:'审批不改变银行余额，实际执行形成资金台账，银行导入用于对账。', claims:'员工报销归集部门，支持借款冲账与剩余款项支付。', assets:'按示例资本化政策区分办公费用和固定资产，折旧生成凭证草稿。', tax:'引用业务原票形成进销项台账；税率和计提规则仅用于演示。', settings:'船舶、单船公司、会计科目与业务费用分类在此统一维护。', history:'2026-10-14 原始快照只读保存，不参与示例账套及正式凭证计算。' }
const columnsBase=[{key:'id',label:'单据编号'},{key:'date',label:'日期'},{key:'description',label:'摘要'},{key:'party',label:'往来方'},{key:'vessel',label:'受益船舶'},{key:'amount',label:'原币金额',money:true,format:(v,r)=>format(v,r.currency)},{key:'remaining',label:'待收／待付',money:true,format:v=>v==null?'—':format(v)},{key:'statusLabel',label:'状态',status:true}]
const enrich=d=>({...d,party:partyName(d.partyId),vessel:vesselName(d.vesselId),remaining:['invoice','bill','reimbursement','asset'].includes(d.type)?engine.outstanding(d,endDate.value):null,statusLabel:STATUS[d.status]||d.status})
const currentBank=computed(()=>accountFilter.value||accounts.value.find(a=>a.kind==='bank')?.id)
const reconciliation=computed(()=>currentBank.value?engine.reconcile(currentBank.value):null)
const reportAccounts=computed(()=>reports.value.accounts.filter(a=>a.balance||a.debit||a.credit))
const agingDocs=computed(()=>moduleId.value==='ar'?arDocs.value:apDocs.value)
const agingRows=computed(()=>agingDocs.value.filter(d=>engine.outstanding(d,endDate.value)>0).map(d=>{const overdue=d.dueDate?Math.max(0,Math.floor((Date.parse(endDate.value)-Date.parse(d.dueDate))/86400000)):null;return {...enrich(d),days:overdue==null?'待补到期日':overdue,bucket:overdue==null?'待补到期日':overdue===0?'未逾期':overdue<=30?'1–30天':overdue<=60?'31–60天':overdue<=90?'61–90天':'90天以上'}}))
const categoryReceivables=computed(()=>arDocs.value.flatMap(d=>{const shares=proportional(d.amount-engine.outstanding(d,endDate.value),d.lines.map(l=>l.amount));return d.lines.map((l,index)=>({id:`${d.id}-${l.id}`,docId:d.id,category:categoryName(l.category),description:l.description,expenseMonth:l.expenseMonth||d.period,amount:l.amount,received:shares[index],remaining:l.amount-shares[index]}))}))
const categoryTotals=computed(()=>CATEGORIES.map(c=>({...c,amount:arDocs.value.flatMap(d=>d.lines.map(l=>({...l,rate:d.rate}))).filter(l=>l.category===c.id).reduce((n,l)=>n+convert(l.amount,l.rate),0)})))
const allScopedJournals=computed(()=>engine.scoped(data.journals,{allPeriods:true}).filter(j=>j.date<=endDate.value))
const selectedLedger=computed(()=>reports.value.accounts.find(a=>a.id===accountFilter.value))
const tableConfig=computed(()=>{
 const m=moduleId.value,p=pageId.value
 let rows=[],columns=columnsBase
 if(m==='ar'&&p==='contracts') return {rows:data.contracts.filter(c=>c.companyId===context.companyId&&(!context.vesselId||c.vesselId===context.vesselId)).map(c=>({...c,vessel:vesselName(c.vesselId),party:partyName(c.partyId),statusLabel:c.status==='active'?'生效中':'停用',prorateLabel:c.prorate==='actual'?'首末月按实际天数':'首末月按整月'})),columns:[{key:'id',label:'合同编号'},{key:'vessel',label:'船舶'},{key:'party',label:'单船公司'},{key:'monthlyFee',label:'固定月费',money:true,format:v=>format(v)},{key:'start',label:'生效日期'},{key:'end',label:'终止日期'},{key:'prorateLabel',label:'折算方式'},{key:'statusLabel',label:'状态'}]}
 if(['ar','ap'].includes(m)&&p==='aging') return {rows:agingRows.value.map(d=>({...d,bankslips:data.attachments.filter(att=>att.kind==='BankSlip'&&data.allocations.some(a=>a.docId===d.id&&a.sourceId===att.entityId)).map(a=>a.name).join(' / ')||'待补'})),columns:[...columnsBase.slice(0,6),...(m==='ap'?[{key:'bankslips',label:'关联 BankSlip'}]:[]),{key:'remaining',label:'未核销余额',money:true,format:v=>format(v)},{key:'dueDate',label:'到期日'},{key:'days',label:'逾期天数'},{key:'bucket',label:'账龄分组'}]}
 if(m==='gl'&&p==='journals') return {rows:journals.value.map(j=>({...j,amount:sum(j.lines,'debit'),party:j.sourceId,statusLabel:STATUS[j.status],vessel:vesselName(j.vesselId)})),columns:[{key:'id',label:'凭证编号'},{key:'date',label:'记账日期'},{key:'description',label:'摘要'},{key:'party',label:'来源单据'},{key:'amount',label:'借方合计',money:true,format:v=>format(v)},{key:'statusLabel',label:'状态',status:true}]}
 if(m==='gl'&&p==='ledger') return {rows:reportAccounts.value,columns:[{key:'id',label:'科目代码'},{key:'name',label:'会计科目'},{key:'opening',label:'期初借贷差',money:true,format:v=>format(v)},{key:'debit',label:'本期借方',money:true,format:v=>format(v)},{key:'credit',label:'本期贷方',money:true,format:v=>format(v)},{key:'balance',label:'期末借贷差',money:true,format:v=>format(v)}]}
 if(m==='treasury'&&p==='accounts')return {rows:accounts.value.map(a=>({...a,balance:engine.balance(a.id,endDate.value),vessel:vesselName(a.vesselId),kindLabel:a.kind==='bank'?'银行账户':'现金账户'})),columns:[{key:'name',label:'账户名称'},{key:'number',label:'示例账号'},{key:'kindLabel',label:'类型'},{key:'currency',label:'币种'},{key:'vessel',label:'所属船舶'},{key:'balance',label:'台账余额',money:true,format:v=>format(v)}]}
 if(m==='treasury'&&p==='movements')return {rows:engine.scoped(data.movements).map(x=>({...x,account:data.accounts.find(a=>a.id===x.accountId)?.name,vessel:vesselName(x.vesselId),amount:x.signedAmount})),columns:[{key:'id',label:'流水编号'},{key:'date',label:'日期'},{key:'account',label:'资金账户'},{key:'vessel',label:'受益船'},{key:'description',label:'摘要'},{key:'amount',label:'收支金额',money:true,format:v=>format(v)},{key:'sourceId',label:'业务来源'}]}
 if(m==='treasury'&&p==='bank')return {rows:engine.scoped(data.statements).filter(s=>!accountFilter.value||s.accountId===accountFilter.value).map(s=>({...s,amount:s.signedAmount,remaining:Math.abs(s.signedAmount)-sum(data.matches.filter(x=>x.statementId===s.id)),statusLabel:Math.abs(s.signedAmount)===sum(data.matches.filter(x=>x.statementId===s.id))?'已匹配':'待匹配'})),columns:[{key:'reference',label:'银行外部流水号'},{key:'date',label:'日期'},{key:'description',label:'银行摘要'},{key:'amount',label:'收支金额',money:true,format:v=>format(v)},{key:'remaining',label:'未匹配金额',money:true,format:v=>format(v)},{key:'statusLabel',label:'对账状态'}]}
 if(m==='claims'&&p==='departments'){
 const groups={};for(const d of apDocs.value.filter(d=>d.type==='reimbursement')){const key=d.department||'待分配';groups[key]??={id:key,name:key,amount:0,remaining:0,count:0};groups[key].amount+=convert(d.amount,d.rate);groups[key].remaining+=convert(engine.outstanding(d),d.rate);groups[key].count++}return {rows:Object.values(groups),columns:[{key:'name',label:'部门'},{key:'count',label:'报销单数'},{key:'amount',label:'已审核报销额',money:true,format:v=>format(v)},{key:'remaining',label:'未核销余额',money:true,format:v=>format(v)}]}
 }
 if(m==='tax'&&p==='register')return {rows:asOfDocs.value.filter(d=>['invoice','bill','reimbursement','asset'].includes(d.type)&&['approved','executed'].includes(d.status)).map(d=>({...enrich(d),direction:d.type==='bill'?'销项':'进项',taxLabel:d.tax?format(d.tax):'0.00（示例）'})),columns:[{key:'id',label:'业务原票编号'},{key:'number',label:'发票／账单号'},{key:'date',label:'日期'},{key:'direction',label:'方向'},{key:'party',label:'往来方'},{key:'amount',label:'含税金额',money:true,format:(v,r)=>format(v,r.currency)},{key:'taxLabel',label:'登记税额',money:true}]}
 if(m==='settings'){
 if(p==='companies')return {rows:data.companies.filter(c=>engine.role().companies.includes(c.id)),columns:[{key:'id',label:'账套代码'},{key:'name',label:'公司名称'},{key:'currency',label:'本位币'},{key:'kind',label:'主体类型',format:v=>kindLabel(v)}]}
 if(p==='departments')return {rows:data.departments,columns:[{key:'id',label:'部门代码'},{key:'name',label:'部门名称'}]}
 if(p==='organizations')return {rows:data.vessels.filter(v=>context.companyId==='MSTS'||v.companyId===context.companyId).map(v=>({...v,company:companyName(v.companyId),owner:partyName(v.ownerId)})),columns:[{key:'name',label:'船名'},{key:'imo',label:'IMO / 示例标识'},{key:'company',label:'单船公司'},{key:'owner',label:'船东'},{key:'bank',label:'船东付款银行'},{key:'start',label:'管理开始'}]}
 if(p==='parties')return {rows:data.parties,columns:[{key:'id',label:'档案代码'},{key:'name',label:'名称'},{key:'kind',label:'角色类型'},{key:'department',label:'部门'}]}
 if(p==='accounts')return {rows:data.chart,columns:[{key:'id',label:'会计科目代码'},{key:'name',label:'会计科目名称'},{key:'kind',label:'报表性质',format:v=>kindLabel(v)},{key:'enabled',label:'启用',format:v=>v?'已启用':'已停用'}]}
 if(p==='audit')return {rows:engine.scoped(data.audit,{allPeriods:true}),columns:[{key:'at',label:'操作时间',format:v=>new Date(v).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})},{key:'action',label:'操作'},{key:'entityId',label:'单据／对象'},{key:'user',label:'操作人'},{key:'role',label:'角色'},{key:'detail',label:'说明'}]}
 }
 const types={ 'ar/bills':['bill'],'ar/receipts':['receipt'],'ap/invoices':['invoice'],'ap/payments':['payment'],'treasury/cash':['transfer','cashSpend'],'treasury/funding':['funding'],'treasury/instruments':['instrument'],'claims/reimbursements':['reimbursement'],'claims/loans':['loan','loanReturn'],'assets/register':['asset'],'assets/depreciation':['asset'] }[`${m}/${p}`]||[]
 rows=docs.value.filter(d=>types.includes(d.type)).map(enrich)
 if(tableFilter.value!=='all')rows=rows.filter(d=>tableFilter.value==='outstanding'?engine.outstanding(d)>0:d.status===tableFilter.value)
 if(m==='claims'&&p==='loans')columns=[...columnsBase.slice(0,6),{key:'loanBalance',label:'未还借款',money:true,format:(v,r)=>r.type==='loan'?format(engine.loanBalance(r.id)):'—'},columnsBase.at(-1)]
 if(m==='assets')columns=[...columnsBase.slice(0,6),{key:'depreciated',label:'累计计提',money:true,format:(v,r)=>format(engine.depreciated(r.id,context.period))},{key:'assetStatus',label:'资产状态',format:v=>STATUS[v]||'待审核'},columnsBase.at(-1)]
 return {rows,columns}
})
function show(row){
 if(moduleId.value==='ar'&&pageId.value==='contracts'){openMaster('contracts',row);return}
 if(moduleId.value==='gl'&&pageId.value==='ledger'){accountFilter.value=row.id;return}
 if(moduleId.value==='treasury'&&pageId.value==='bank'){openMatch(row);return}
 if(moduleId.value==='settings'&&['companies','organizations','parties','departments','accounts'].includes(pageId.value)){openMaster({companies:'companies',organizations:'vessels',parties:'parties',departments:'departments',accounts:'chart'}[pageId.value],row);return}
 if(moduleId.value==='treasury'&&pageId.value==='accounts'){openMaster('accounts',row);return}
 if(moduleId.value==='settings'&&pageId.value==='audit'){if(data.documents.some(d=>d.id===row.entityId)){selectedId.value=row.entityId;selectedKind.value='document';detailTab.value='操作记录'}return}
 if(moduleId.value==='claims'&&pageId.value==='departments'){router.push('/app/claims/reimbursements');return}
 selectedKind.value=moduleId.value==='gl'?'journal':moduleId.value==='treasury'&&pageId.value==='movements'?'movement':'document';selectedId.value=row.id;detailTab.value='明细';detailNote.value='';executionDate.value=row.date?.slice(0,7)===context.period?row.date:`${context.period}-15`
}
async function act(fn,message){try{return await perform(fn,message)}catch{return null}}
function start(type,initial={}){
 formType.value=type;modal.value='document';dbState.error=''
 Object.keys(form).forEach(k=>delete form[k])
 const defaultVessel=context.vesselId||(context.companyId==='MSTS'?'':data.vessels.find(v=>v.companyId===context.companyId)?.id||'')
 Object.assign(form,{description:'',partyId:type==='reimbursement'||type==='loan'||type==='loanReturn'?'EMP-1':'VENDOR-1',vesselId:defaultVessel,date:`${context.period}-15`,expenseMonth:context.period,dueDate:`${context.period}-28`,amount:'',currency:'USD',rate:'1',tax:'0',number:'',category:'OWNER',claimable:false,costCenter:'船管／备件',department:'机务部',accountId:`BANK-${context.companyId}`,targetAccountId:`CASH-${context.companyId}`,fee:'0',feeClaimable:false,lifeMonths:data.policy.assetLife,residual:'0',depreciationStart:context.period,location:'MSTS 办公室',loanId:'',instrumentKind:'支票',crossCompanyId:context.companyId,...initial})
 if(type==='cashSpend')form.accountId=`CASH-${context.companyId}`
 if(type==='funding')form.partyId='SHIP-A'
 if(type==='asset')form.depreciationStart=data.policy.depreciationStart==='nextMonth'?new Date(Date.UTC(Number(context.period.slice(0,4)),Number(context.period.slice(5,7)),1)).toISOString().slice(0,7):context.period
 lineInputs.value=[];allocationInputs.value=[]
}
const roleRows=computed(()=>ROLES.map(r=>({...r,...(data.roleGrants?.[r.id]||{}),...(r.id==='demo'?{companies:data.companies.map(c=>c.id)}:{})})))
const filterOptions=computed(()=>moduleId.value==='gl'?[['all','全部'],['draft','草稿'],['submitted','待审核'],['approved','已审核'],['posted','已过账'],['void','已作废']]:[['all','全部'],['draft','草稿'],['submitted','待审核'],['approved','已审核'],['executed','已执行'],['outstanding','未结清']])
const visibleTableRows=computed(()=>{const rows=tableConfig.value.rows;if(tableFilter.value==='all')return rows;if(tableFilter.value==='outstanding')return rows.filter(r=>['invoice','bill','asset','reimbursement'].includes(r.type)&&engine.outstanding(r)>0);return rows.filter(r=>r.status===tableFilter.value)})
const eligibleTargets=computed(()=>{
 const type=formType.value
 return data.documents.filter(d=>['approved','executed'].includes(d.status)&&engine.role().companies.includes(d.companyId)&&engine.outstanding(d)>0&&d.currency===form.currency&&d.partyId===form.partyId&&(!form.vesselId||d.vesselId===form.vesselId)&&(type==='receipt'?d.type==='bill'&&d.companyId===context.companyId:['invoice','reimbursement','asset'].includes(d.type)&&d.companyId===form.crossCompanyId))
})
const eligibleLoans=computed(()=>data.documents.filter(d=>d.companyId===context.companyId&&d.type==='loan'&&d.status==='executed'&&d.partyId===form.partyId&&engine.loanBalance(d.id)>0))
function addLine(){lineInputs.value.push({description:'',amount:'',category:'OWNER',costCenter:'船管／备件',claimable:false,claimAmount:'',tax:'0'})}
function toggleAllocation(d,event){if(event.target.checked)allocationInputs.value.push({docId:d.id,amount:String(engine.outstanding(d)/100)});else allocationInputs.value=allocationInputs.value.filter(a=>a.docId!==d.id)}
async function saveDocument(){
 const result=await act(()=>{
  const input={...form,amount:cents(form.amount),tax:cents(form.tax||'0'),fee:cents(form.fee||'0'),residual:cents(form.residual||'0'),lifeMonths:Number(form.lifeMonths),allocations:allocationInputs.value.map(a=>({docId:a.docId,amount:cents(a.amount)}))}
  if(!['payment','receipt','loan','loanReturn','transfer','cashSpend','funding'].includes(formType.value))delete input.accountId
  if(lineInputs.value.length)input.lines=lineInputs.value.map(l=>({...l,amount:cents(l.amount),claimAmount:l.claimable?cents(l.claimAmount||l.amount):0,tax:cents(l.tax||'0')}))
  if(formType.value==='receipt')input.purposeAllocations=CATEGORIES.map(c=>({category:c.id,amount:cents(form['purpose_'+c.id]||'0')})).filter(a=>a.amount>0)
  return engine.create(formType.value,input)
 },'单据草稿已创建，请提交审核')
 if(result){modal.value='';selectedKind.value='document';selectedId.value=result.id;detailTab.value='明细';executionDate.value=result.date}
}
function openBill(){modal.value='bill';Object.assign(form,{contractId:data.contracts.find(c=>!context.vesselId||c.vesselId===context.vesselId)?.id,includeFee:true})}
async function saveBill(){const d=await act(()=>engine.generateBill(form.contractId,{includeFee:form.includeFee}),'账单草稿已生成，已排除重复来源');if(d){modal.value='';selectedKind.value='document';selectedId.value=d.id;detailTab.value='明细'}}
async function executeSelected(){
 const d=detailDoc.value
 const result=await act(()=>engine.execute(d.id,{accountId:d.accountId||`BANK-${d.companyId}`,date:executionDate.value||undefined,fee:d.fee||0,feeClaimable:d.feeClaimable}),'实际资金和核销已登记，关联凭证保留草稿')
 if(result)detailTab.value='关联单据'
}
async function approveSelected(){await act(()=>engine.approve(detailDoc.value.id),'审核通过；请查看关联凭证和跨账套记录')}
function openJournal(){modal.value='journal';Object.assign(form,{description:'',date:`${context.period}-15`});manualLines.value=[{account:'5602',debit:'',credit:'0',cashFlow:'operating'},{account:'2202',debit:'0',credit:'',cashFlow:'operating'}]}
async function saveJournal(){const j=await act(()=>engine.createJournal({description:form.description,date:form.date,vesselId:context.vesselId,lines:manualLines.value.map(l=>({...l,debit:cents(l.debit||'0'),credit:cents(l.credit||'0')}))}),'凭证草稿已创建');if(j){modal.value='';selectedId.value=j.id;selectedKind.value='journal';detailTab.value='明细'}}
function openMaster(collection,row={}){modal.value='master';formType.value=collection;Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,{name:'',kind:collection==='accounts'?'bank':collection==='chart'?'expense':collection==='companies'?'vessel':'供应商',enabled:true,department:'',currency:'USD',vesselId:context.vesselId,partyId:'SHIP-A',companyId:context.companyId,monthlyFee:'10000',start:'2026-10-01',end:'',prorate:'actual',status:'active',imo:'',bank:'示例银行',ownerId:'SHIP-A',...row,originalId:row.id});if(collection==='contracts')form.monthlyFee=String((row.monthlyFee||1000000)/100)}
async function saveMaster(){const r=await act(()=>engine.saveMaster(formType.value,{...form,...(formType.value==='contracts'?{monthlyFee:cents(form.monthlyFee)}:{})}),'基础档案已保存');if(r)modal.value=''}
function openPolicy(){modal.value='policy';Object.assign(form,{...data.policy,capitalThreshold:String(data.policy.capitalThreshold/100)})}
async function savePolicy(){const r=await act(()=>{engine.savePolicy({...form,capitalThreshold:cents(form.capitalThreshold),assetLife:Number(form.assetLife)});return true},'示例政策已保存');if(r)modal.value=''}
async function upload(event){const file=event.target.files?.[0];if(!file)return;try{await attach(selectedId.value,file,detailDoc.value?.type==='payment'?'BankSlip':'业务附件');dbState.message='附件已保存至本浏览器'}catch(e){dbState.error=e.message}event.target.value=''}
async function previewFile(a){const file=await getFile(a.id);if(!file){dbState.error='当前浏览器找不到附件内容';return}const url=URL.createObjectURL(file);const link=document.createElement('a');link.href=url;link.download=a.name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function printPage(){window.print()}
async function importBank(event){try{const file=event.target.files?.[0];if(!file)return;const rows=parseCsv(await file.text());const headers=rows.shift();const names=['date','reference','amount','description'];if(!names.slice(0,3).every(n=>headers.includes(n)))throw new Error('CSV 须包含 date,reference,amount,description 列，支出用负数');importRows.value=rows.map(r=>({date:r[headers.indexOf('date')],reference:r[headers.indexOf('reference')],signedAmount:cents(r[headers.indexOf('amount')]),description:r[headers.indexOf('description')]||''}));importFile.value=file.name;modal.value='import'}catch(e){dbState.error=e.message}event.target.value=''}
async function confirmImport(){const n=await act(()=>engine.importStatements(importRows.value,currentBank.value),'银行流水已导入；资金余额未改变');if(n!==null){modal.value='';dbState.message=`新增 ${n} 条，重复外部流水号已跳过`}}
function downloadBankTemplate(){exportCsv('银行流水导入模板',['date','reference','amount','description'],[[`${context.period}-15`,'DEMO-REF-001','-420.00','示例付款400及手续费20']])}
function simulateStatement(){const rows=engine.scoped(data.movements).filter(m=>m.accountId===currentBank.value).map(m=>({date:m.date,reference:`BANK-${m.id}`,signedAmount:m.signedAmount,description:m.description}));if(!rows.length){dbState.error='请先执行一笔收付款，再生成对应示例银行对账单';return}importRows.value=rows;importFile.value='由演示资金台账构造的模拟银行对账单';modal.value='import'}
function openMatch(row){selectedId.value='';modal.value='match';Object.assign(form,{statementId:row.id});matchMovement.value='';matchAmount.value=String(row.remaining/100)}
const matchOptions=computed(()=>{const s=data.statements.find(s=>s.id===form.statementId);return data.movements.filter(m=>m.companyId===context.companyId&&m.accountId===s?.accountId&&Math.sign(m.signedAmount)===Math.sign(s.signedAmount)&&Math.abs(m.signedAmount)>sum(data.matches.filter(x=>x.movementId===m.id)))})
async function saveMatch(){const r=await act(()=>{engine.match(form.statementId,matchMovement.value,cents(matchAmount.value));return true},'银行匹配已确认');if(r)modal.value=''}
function exportStatement(){const rows=agingRows.value;exportCsv(`${title.value}-${context.period}`,['单据','往来方','船舶','收费分类','原币总额','未核销','到期日','账龄'],rows.map(d=>[d.id,d.party,d.vessel,d.lines.map(l=>categoryName(l.category)).join(' / '),format(d.amount,d.currency),format(d.remaining,d.currency),d.dueDate||'待补',d.bucket]))}
async function postAll(){await act(()=>{const pending=journals.value.filter(j=>['draft','submitted','approved'].includes(j.status));for(const j of pending){if(j.status==='draft')engine.journalAction(j.id,'submit');if(j.status==='submitted')engine.journalAction(j.id,'review');if(j.status==='approved')engine.journalAction(j.id,'post')}return true},'本账套当前筛选范围内的凭证已审核过账')}
async function demoAction(step){await act(()=>{
 const invoice=engine.doc('INV-DEMO-1000');if(step===1){if(invoice.status==='draft')engine.submit(invoice.id);engine.approve(invoice.id)}
 if(step===2||step===3){const amount=step===2?40000:60000;const p=engine.create('payment',{description:step===2?'主线第一笔付款400及手续费20':'主线第二笔付款600',partyId:invoice.partyId,vesselId:invoice.vesselId,date:'2026-10-15',amount,allocations:[{docId:invoice.id,amount}]});engine.submit(p.id);engine.approve(p.id);engine.execute(p.id,{fee:step===2?2000:0,feeClaimable:step===2})}
 if(step===4){const fee=data.documents.filter(d=>d.feeSourceId&&d.vesselId===invoice.vesselId);const bill=engine.generateBill('CONTRACT-1',{includeFee:false,sourceIds:[invoice.id,...fee.map(d=>d.id)]});engine.submit(bill.id);engine.approve(bill.id)}
 if(step===5){const bill=data.documents.find(d=>d.type==='bill'&&d.status==='approved'&&d.lines.some(l=>l.sourceId===invoice.id));if(!bill)throw new Error('请先生成1,020美元船东账单');const r=engine.create('receipt',{description:'主线船东回款400',partyId:'SHIP-A',vesselId:invoice.vesselId,date:'2026-10-31',amount:40000,allocations:[{docId:bill.id,amount:40000}]});engine.submit(r.id);engine.approve(r.id);engine.execute(r.id)}
},'主线业务已更新，可到相关模块核对')}
const demoInvoice=computed(()=>data.documents.find(d=>d.id==='INV-DEMO-1000'))
const demoBill=computed(()=>data.documents.find(d=>d.type==='bill'&&d.status!=='void'&&d.lines.some(l=>l.sourceId==='INV-DEMO-1000')))
const demoPayments=computed(()=>data.allocations.filter(a=>a.docId==='INV-DEMO-1000'))
const demoSteps=computed(()=>[
 {n:1,name:'审核原票',text:'应付 1,000；单船确认成本',done:demoInvoice.value.status==='approved',disabled:demoInvoice.value.status==='approved'},
 {n:2,name:'付 400 ＋ 手续费 20',text:'应付降至 600；银行减少 420',done:sum(demoPayments.value)>=40000,disabled:demoInvoice.value.status!=='approved'||demoPayments.value.length>0},
 {n:3,name:'再付 600',text:'供应商结清；船东应收独立',done:sum(demoPayments.value)>=100000,disabled:sum(demoPayments.value)!==40000},
 {n:4,name:'出账 1,020',text:'原票＋可收手续费；不重复计费',done:!!demoBill.value,disabled:sum(demoPayments.value)!==100000||!!demoBill.value},
 {n:5,name:'船东回款 400',text:'应收余 620；双方账目同步',done:!!demoBill.value&&engine.outstanding(demoBill.value)===62000,disabled:!demoBill.value||engine.outstanding(demoBill.value)!==102000},
])
const newDocumentType=computed(()=>({'ar/receipts':'receipt','ap/invoices':'invoice','ap/payments':'payment','treasury/cash':'transfer','treasury/funding':'funding','treasury/instruments':'instrument','claims/reimbursements':'reimbursement','claims/loans':'loan','assets/register':'asset'}[`${moduleId.value}/${pageId.value}`]))
const formParties=computed(()=>formType.value==='receipt'?data.parties.filter(p=>p.kind==='船东／客户'):['loan','loanReturn','reimbursement'].includes(formType.value)?data.parties.filter(p=>p.kind==='员工'):data.parties)
const requiredPurpose=computed(()=>['invoice','reimbursement','asset'].includes(formType.value))
const historyRows=computed(()=>pageId.value==='records'?historic.records.filter(r=>r.sheet==='Expenses Lists').map(r=>({...r,description:r.description,amount:r.invoiceUsd,statusLabel:r.status||'状态缺失',party:r.supplier})):historic.findings.map((f,i)=>({...f,id:f.id||`HIST-${i+1}`})))
</script>
<template>
 <main class="f-page">
  <div class="f-page-heading"><div><p class="f-eyebrow">{{moduleId==='home'?'OVERVIEW / 财务总览':`${module.mark} / ${module.name}`}}</p><h1>{{title}}</h1><p class="f-description">{{notes[moduleId]||'从一笔业务，看到收付款、往来和财务结果。'}}</p></div><div class="f-actions f-print-hide">
   <button v-if="newDocumentType" class="f-btn primary" :disabled="!can('create')" @click="start(newDocumentType)">＋ 新建{{TYPES[newDocumentType]}}</button>
   <button v-if="moduleId==='ar'&&pageId==='bills'" class="f-btn primary" :disabled="!can('create')||context.companyId!=='MSTS'" @click="openBill">＋ 生成月度账单</button>
   <button v-if="moduleId==='ar'&&pageId==='contracts'" class="f-btn primary" :disabled="!can('master')||context.companyId!=='MSTS'" @click="openMaster('contracts')">＋ 新建合同</button>
   <template v-if="moduleId==='gl'&&pageId==='journals'"><button class="f-btn" :disabled="context.roleId!=='demo'" @click="postAll">演示：本账套批量过账</button><button class="f-btn primary" :disabled="!can('create')" @click="openJournal">＋ 手工凭证</button></template>
   <button v-if="moduleId==='claims'&&pageId==='loans'" class="f-btn" :disabled="!can('create')" @click="start('loanReturn')">登记还款</button>
   <button v-if="moduleId==='treasury'&&pageId==='cash'" class="f-btn" :disabled="!can('create')" @click="start('cashSpend')">登记现金消费</button>
   <button v-if="moduleId==='treasury'&&pageId==='accounts'" class="f-btn primary" :disabled="!can('master')" @click="openMaster('accounts')">＋ 新建账户</button>
   <button v-if="moduleId==='settings'&&['companies','departments'].includes(pageId)" class="f-btn primary" :disabled="!can('master')" @click="openMaster(pageId)">＋ 新建档案</button>
   <button v-if="moduleId==='settings'&&pageId==='parties'" class="f-btn primary" :disabled="!can('master')" @click="openMaster('parties')">＋ 新建往来档案</button>
   <button v-if="moduleId==='settings'&&pageId==='organizations'" class="f-btn" :disabled="!can('master')" @click="openMaster('vessels')">＋ 新建船舶</button>
   <button v-if="moduleId==='settings'&&pageId==='accounts'" class="f-btn" :disabled="!can('master')" @click="openMaster('chart')">＋ 会计科目</button>
   <button v-if="(moduleId==='settings'&&pageId==='policies')||(moduleId==='tax'&&pageId==='summary')" class="f-btn" :disabled="!can('master')" @click="openPolicy">配置示例政策</button>
   <button v-if="pageId==='aging'" class="f-btn" @click="exportStatement">导出对账单</button><button v-if="['aging','reports','bills','reconciliation'].includes(pageId)" class="f-btn" @click="printPage">打印</button>
  </div></div>

  <template v-if="moduleId==='home'">
   <section class="f-kpis"><RouterLink class="f-kpi" to="/app/ar/aging"><span>船东应收余额 <i>↗</i></span><strong>{{format(arTotal)}}</strong><small>USD · 已审核账单未核销</small></RouterLink><RouterLink class="f-kpi" to="/app/ap/aging"><span>应付余额 <i>↗</i></span><strong>{{format(apTotal)}}</strong><small>USD · 发票、报销及资产应付</small></RouterLink><RouterLink class="f-kpi" to="/app/treasury/accounts"><span>USD 账户资金 <i>↗</i></span><strong>{{format(funds)}}</strong><small>USD · 当前账套银行及现金</small></RouterLink><RouterLink class="f-kpi dark" to="/app/gl/journals"><span>待处理凭证 <i>↗</i></span><strong>{{journals.filter(j=>!['posted','void'].includes(j.status)).length}}<em>笔</em></strong><small>审核后过账，更新财务报表</small></RouterLink></section>
   <section class="f-dashboard-grid"><article class="f-card"><div class="f-section-heading"><div><p class="f-eyebrow">RECEIVABLES</p><h2>船东收费构成</h2></div><RouterLink class="f-link" to="/app/ar/bills">查看账单 ↗</RouterLink></div><div class="f-category" v-for="(c,i) in categoryTotals" :key="c.id"><div><span><i :style="{background:['#176a66','#3f8198','#92ac9c','#c9ac77','#b17861'][i]}"></i>{{c.name}}</span><b>{{format(c.amount)}}</b></div><div class="f-bar"><span :style="{width:`${Math.max(1,c.amount/Math.max(1,sum(categoryTotals))*100)}%`,background:['#176a66','#3f8198','#92ac9c','#c9ac77','#b17861'][i]}"></span></div></div><p class="f-small">已审核账单总额 · 不包含运营拨款和未出账成本</p></article>
    <article class="f-card"><div class="f-section-heading"><div><p class="f-eyebrow">TO DO</p><h2>本期财务待办</h2></div><span class="f-status">{{context.period}}</span></div><RouterLink class="f-todo" to="/app/ap/invoices"><span class="f-todo-icon">01</span><div><b>审核业务原票</b><small>确认抬头、受益船及费用承担</small></div><strong>{{docs.filter(d=>['draft','submitted'].includes(d.status)&&['invoice','reimbursement'].includes(d.type)).length}}</strong></RouterLink><RouterLink class="f-todo" to="/app/gl/journals"><span class="f-todo-icon">02</span><div><b>凭证审核与过账</b><small>逐账套确认，正式报表只取已过账凭证</small></div><strong>{{journals.filter(j=>!['posted','void'].includes(j.status)).length}}</strong></RouterLink><RouterLink class="f-todo" to="/app/treasury/reconciliation"><span class="f-todo-icon">03</span><div><b>银行核对与未达账项</b><small>确认实际流水与收付款业务一致</small></div><span>↗</span></RouterLink><RouterLink class="f-todo" to="/app/gl/periods"><span class="f-todo-icon">04</span><div><b>期间检查与结账</b><small>审核、折旧、对账及损益结转</small></div><span>↗</span></RouterLink></article></section>
   <section class="f-card f-walkthrough"><div class="f-section-heading"><div><p class="f-eyebrow">CONNECTED WORKFLOW</p><h2>一笔备件费用，从发票到船东回款</h2></div><span class="f-status">{{demoSteps.filter(s=>s.done).length}} / 5 完成</span></div><p class="f-description">每一步创建实际示例单据、资金流水和凭证草稿。操作后可切换模块、账套核对结果。</p><div class="f-demo-steps"><button v-for="step in demoSteps" :key="step.n" :disabled="step.disabled||context.companyId!=='MSTS'||context.roleId!=='demo'||context.period!=='2026-10'" :class="{done:step.done}" @click="demoAction(step.n)"><span>{{step.done?'✓':`0${step.n}`}}</span><b>{{step.name}}</b><small>{{step.text}}</small></button></div><div class="f-inline-metrics"><span>原票待付 <b>{{format(engine.outstanding(demoInvoice))}}</b></span><span>该笔船东待收 <b>{{demoBill?format(engine.outstanding(demoBill)):'尚未出账'}}</b></span><RouterLink class="f-link" to="/app/gl/journals">查看关联凭证 ↗</RouterLink></div></section>
   <div class="f-bottom-links"><RouterLink to="/app/claims/reimbursements">员工报销 <span>借款与费用冲账 ↗</span></RouterLink><RouterLink to="/app/assets/register">固定资产 <span>台账、折旧与盘点 ↗</span></RouterLink><RouterLink to="/app/history/snapshot">历史 Excel 快照 <span>真实数据只读溯源 ↗</span></RouterLink></div>
  </template>

  <template v-else-if="moduleId==='gl'&&pageId==='reports'">
   <div class="f-callout" v-if="context.vesselId">当前为船舶辅助核算视图。查看整个账套的三大报表请清除船舶筛选。</div><div class="f-report-title"><b>{{companyName(context.companyId)}}</b><span>{{context.period}} · USD · 仅已过账凭证</span></div>
   <div class="f-tabs"><button :class="{active:reportTab==='balance'}" @click="reportTab='balance'">资产负债表</button><button :class="{active:reportTab==='income'}" @click="reportTab='income'">利润表</button><button :class="{active:reportTab==='cashflow'}" @click="reportTab='cashflow'">现金流量表</button></div>
   <template v-if="reportTab==='balance'"><div class="f-kpis compact"><article class="f-kpi"><span>资产合计</span><strong>{{format(reports.assets)}}</strong></article><article class="f-kpi"><span>负债合计</span><strong>{{format(reports.liabilities)}}</strong></article><article class="f-kpi"><span>权益及未结转损益</span><strong>{{format(reports.equity)}}</strong></article><article class="f-kpi"><span>核对结果</span><strong :class="reports.balanced?'f-good':'f-bad'">{{reports.balanced?'平衡':'有差额'}}</strong></article></div><FinanceTable title="资产负债表科目" :rows="reportAccounts.filter(a=>!['income','expense'].includes(a.kind))" :columns="[{key:'id',label:'科目代码'},{key:'name',label:'项目'},{key:'kind',label:'性质',format:v=>kindLabel(v)},{key:'balance',label:'期末借贷差',money:true,format:v=>format(v)}]" @select="row=>router.push({path:'/app/gl/ledger',query:{account:row.id}})" /></template>
   <template v-else-if="reportTab==='income'"><div class="f-kpis three"><article class="f-kpi"><span>本期服务收入</span><strong>{{format(reports.revenue)}}</strong></article><article class="f-kpi"><span>本期成本及费用</span><strong>{{format(reports.expenses)}}</strong></article><article class="f-kpi dark"><span>本期利润</span><strong>{{format(reports.profit)}}</strong></article></div><FinanceTable title="利润表" :rows="reportAccounts.filter(a=>['income','expense'].includes(a.kind))" :columns="[{key:'id',label:'科目'},{key:'name',label:'利润项目'},{key:'debit',label:'本期借方',money:true,format:v=>format(v)},{key:'credit',label:'本期贷方',money:true,format:v=>format(v)}]" @select="row=>router.push({path:'/app/gl/ledger',query:{account:row.id}})" /><p class="f-small">利润汇总排除损益结转分录，保持结转前后的本期经营结果一致。</p></template>
   <template v-else><div class="f-kpis three"><article class="f-kpi" v-for="[key,label] in [['operating','经营活动净现金流'],['investing','投资活动净现金流'],['financing','筹资活动净现金流']]" :key="key"><span>{{label}}</span><strong>{{format(reports.flow[key])}}</strong></article></div><FinanceTable title="现金流量凭证明细" :rows="journals.filter(j=>j.status==='posted').flatMap(j=>j.lines.filter(l=>['1001','1002'].includes(l.account)&&['operating','investing','financing'].includes(l.cashFlow)).map((l,i)=>({...l,id:`${j.id}-${i}`,journalId:j.id,description:j.description,amount:l.debit-l.credit})))" :columns="[{key:'journalId',label:'凭证'},{key:'description',label:'摘要'},{key:'cashFlow',label:'现金流分类',format:v=>cashFlowLabel(v)},{key:'amount',label:'净流量',money:true,format:v=>format(v)}]" @select="row=>{selectedId=row.journalId;selectedKind='journal'}" /><p class="f-small">直接法示例：内部划拨与期初余额不计入本期现金流；手工现金分录必须指定分类。</p></template>
  </template>

  <template v-else-if="moduleId==='gl'&&pageId==='periods'">
   <section class="f-card"><div class="f-section-heading"><div><h2>{{context.period}} 期末检查</h2><p class="f-description">检查整个账套，逐项处理阻断条件后再结账。</p></div><span class="f-status">{{companyName(context.companyId)}}</span></div><div class="f-check" v-for="check in engine.periodChecks()" :key="check.name"><span :class="check.pass?'f-good':'f-warn'">{{check.pass?'✓':'○'}}</span><b>{{check.name}}</b><span>{{check.pass?'已通过':`${check.count} 项待处理`}}</span></div><div class="f-actions"><button class="f-btn" :disabled="!can('close')" @click="act(()=>engine.closePeriod('closing'),'损益结转草稿已生成，请前往总账审核过账')">生成损益结转</button><button class="f-btn primary" :disabled="!can('close')" @click="act(()=>engine.closePeriod('close'),'本期已结账，历史业务已锁定')">执行结账</button></div></section><section class="f-card"><h2>反结账</h2><p class="f-description">仅允许最近已结期间，说明原因并保留完整审计记录。</p><div class="f-inline-form"><input v-model="detailNote" aria-label="反结账原因" placeholder="填写反结账原因" /><button class="f-btn" :disabled="!can('close')||!detailNote.trim()" @click="act(()=>engine.closePeriod('reopen',detailNote),'期间已重新开放')">反结账</button></div></section>
  </template>

  <template v-else-if="moduleId==='treasury'&&pageId==='reconciliation'">
