   <div v-if="detailDoc.lines?.length" class="f-table-scroll"><table><thead><tr v-if="selectedKind==='journal'"><th>会计科目</th><th>辅助核算</th><th class="num">借方</th><th class="num">贷方</th></tr><tr v-else><th>业务明细</th><th>收费分类</th><th>成本分类</th><th>所属月</th><th class="num">金额</th><th>来源</th></tr></thead><tbody><tr v-for="(l,i) in detailDoc.lines" :key="l.id||i"><template v-if="selectedKind==='journal'"><td>{{l.account}} {{data.chart.find(a=>a.id===l.account)?.name}}</td><td>{{partyName(l.partyId)}} {{l.department}}</td><td class="num">{{format(l.debit)}}</td><td class="num">{{format(l.credit)}}</td></template><template v-else><td>{{l.description}}</td><td>{{categoryName(l.category)}}<small v-if="l.claimable" class="f-good"> · 可向船东收取</small></td><td>{{l.costCenter}}</td><td>{{l.expenseMonth||detailDoc.expenseMonth}}</td><td class="num">{{format(l.amount)}}</td><td><button v-if="data.documents.some(d=>d.id===l.sourceId)" class="f-link" @click="selectedId=l.sourceId">{{l.sourceId}}</button><span v-else>{{l.sourceId||'业务录入'}}</span></td></template></tr></tbody></table></div>
