    <button v-if="detailDoc.status==='draft'" class="f-btn primary" :disabled="!can('submit')" @click="act(()=>engine.submit(detailDoc.id),'已提交审核')">提交审核</button>
    <button v-if="detailDoc.status==='submitted'" class="f-btn primary" :disabled="!can(['payment','loan','transfer','instrument'].includes(detailDoc.type)?'approvePayment':'review')" @click="approveSelected">审核／审批通过</button>
    <input v-if="detailDoc.status==='approved'&&['payment','receipt','loan','loanReturn','transfer','cashSpend','funding'].includes(detailDoc.type)" v-model="executionDate" type="date" aria-label="实际执行日期"/><button v-if="detailDoc.status==='approved'&&['payment','receipt','loan','loanReturn','transfer','cashSpend','funding'].includes(detailDoc.type)" class="f-btn primary" :disabled="!can('execute')" @click="executeSelected">{{detailDoc.type==='funding'?'登记真实到账':'登记实际执行与核销'}}</button>
    <button v-if="['invoice','reimbursement','asset'].includes(detailDoc.type)&&engine.outstanding(detailDoc)>0" class="f-btn" :disabled="!can('create')" @click="start('payment',{description:`支付 ${detailDoc.id}`,partyId:detailDoc.partyId,vesselId:detailDoc.vesselId,amount:String(engine.outstanding(detailDoc)/100),crossCompanyId:detailDoc.companyId});allocationInputs=[{docId:detailDoc.id,amount:String(engine.outstanding(detailDoc)/100)}];selectedId=''">申请付款</button>
    <button v-if="detailDoc.type==='instrument'&&detailDoc.status==='approved'" class="f-btn" :disabled="!can('create')" @click="start('payment',{description:`票据兑付 ${detailDoc.number||detailDoc.id}`,instrumentId:detailDoc.id,partyId:detailDoc.partyId,vesselId:detailDoc.vesselId,amount:String(detailDoc.amount/100),crossCompanyId:detailDoc.companyId});selectedId=''">申请票据兑付</button>
    <button v-if="detailDoc.type==='bill'&&engine.outstanding(detailDoc)>0" class="f-btn" :disabled="!can('create')" @click="start('receipt',{description:`收款 ${detailDoc.id}`,partyId:detailDoc.partyId,vesselId:detailDoc.vesselId,amount:String(engine.outstanding(detailDoc)/100),date:detailDoc.date});allocationInputs=[{docId:detailDoc.id,amount:String(engine.outstanding(detailDoc)/100)}];selectedId=''">登记回款</button>
    <button v-if="detailDoc.type==='reimbursement'&&detailDoc.status==='approved'" class="f-btn" :disabled="!can('allocate')" @click="modal='offset';form.loanId=data.documents.find(d=>d.type==='loan'&&d.companyId===context.companyId&&d.partyId===detailDoc.partyId&&engine.loanBalance(d.id)>0)?.id||'';form.amount=String(engine.outstanding(detailDoc)/100)">报销冲借款</button>
    <button v-if="['payment','receipt'].includes(detailDoc.type)&&detailDoc.status==='executed'&&detailDoc.amount>sum(data.allocations.filter(a=>a.sourceId===detailDoc.id&&!a.mirrored&&!a.loanId))" class="f-btn" :disabled="!can('allocate')" @click="modal='allocate';formType=detailDoc.type;Object.assign(form,{partyId:detailDoc.partyId,vesselId:detailDoc.vesselId,currency:detailDoc.currency,crossCompanyId:detailDoc.companyId});allocationInputs=[]">分配剩余预收／预付</button>
    <template v-if="['draft','submitted'].includes(detailDoc.status)"><input v-model="detailNote" class="f-reason-input" aria-label="退回或作废原因" placeholder="退回／作废原因"/><button v-if="detailDoc.status==='submitted'" class="f-btn" :disabled="!can('review')||!detailNote.trim()" @click="act(()=>engine.reject(detailDoc.id,detailNote),'单据已退回草稿')">退回</button><button class="f-btn danger" :disabled="!can('create')||!detailNote.trim()" @click="act(()=>engine.voidDocument(detailDoc.id,detailNote),'单据已作废')">作废</button></template>
   </template>
   <template v-else-if="selectedKind==='journal'"><button v-if="detailDoc.status==='draft'" class="f-btn primary" :disabled="!can('submit')" @click="act(()=>engine.journalAction(detailDoc.id,'submit'),'凭证已提交')">提交凭证</button><button v-if="detailDoc.status==='submitted'" class="f-btn primary" :disabled="!can('journalReview')" @click="act(()=>engine.journalAction(detailDoc.id,'review'),'凭证审核通过')">审核通过</button><button v-if="detailDoc.status==='approved'" class="f-btn primary" :disabled="!can('post')" @click="act(()=>engine.journalAction(detailDoc.id,'post'),'凭证已过账，账簿报表已更新')">过账</button><input v-if="['draft','submitted','posted'].includes(detailDoc.status)" v-model="detailNote" class="f-reason-input" aria-label="凭证更正原因" placeholder="退回、作废或冲销原因"/><button v-if="detailDoc.status==='submitted'" class="f-btn" :disabled="!can('journalReview')||!detailNote.trim()" @click="act(()=>engine.journalAction(detailDoc.id,'reject',detailNote),'凭证已退回')">退回</button><button v-if="['draft','submitted'].includes(detailDoc.status)" class="f-btn danger" :disabled="!can('create')||!detailNote.trim()" @click="act(()=>engine.journalAction(detailDoc.id,'void',detailNote),'凭证已作废')">作废</button><button v-if="detailDoc.status==='posted'" class="f-btn danger" :disabled="!can('post')||!detailNote.trim()" @click="act(()=>engine.journalAction(detailDoc.id,'reverse',detailNote),'冲销草稿已生成，请另行审核过账；真实资金事实保留')">生成冲销凭证</button></template>
   <button class="f-btn subtle" @click="selectedId=''">关闭</button>
  </div>
 </FinanceDialog>

 <FinanceDialog v-if="modal==='document'" :title="`新建${TYPES[formType]}`" wide @close="modal=''">
  <form class="f-form" @submit.prevent="saveDocument">
   <label class="full">业务摘要<input v-model="form.description" required placeholder="说明发生了什么、由谁承担" /></label>
   <label>业务日期<input v-model="form.date" type="date" required /></label><label>受益船舶<select v-model="form.vesselId" aria-label="单据受益船"><option value="" v-if="context.companyId==='MSTS'">MSTS 本部／未指定</option><option v-for="v in data.vessels.filter(v=>context.companyId==='MSTS'||v.companyId===context.companyId||formType==='payment')" :key="v.id" :value="v.id">{{v.name}} · {{v.imo}}</option></select></label>
   <label>供应商／员工／船东<select v-model="form.partyId"><option v-for="p in formParties" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>{{formType==='receipt'?'收款毛额':'原币金额'}}<input v-model="form.amount" inputmode="decimal" required placeholder="0.00" /></label>
   <label>币种<select v-model="form.currency"><option v-for="c in ['USD','CNY','HKD','EUR']" :key="c">{{c}}</option></select></label><label>每单位原币折 USD<input v-model="form.rate" inputmode="decimal" required /></label>
   <template v-if="requiredPurpose"><label v-if="formType==='invoice'">发票编号<input v-model="form.number" required placeholder="供应商发票号，用于防重" /></label><label>到期日<input v-model="form.dueDate" type="date" /></label><label>费用所属月<input v-model="form.expenseMonth" type="month" /></label><label>部门<select v-model="form.department"><option v-for="d in data.departments" :key="d.id" :value="d.name">{{d.name}}</option></select></label><label>登记税额<input v-model="form.tax" inputmode="decimal" /></label></template>
   <template v-if="formType==='invoice'"><label>收费分类<select v-model="form.category"><option v-for="c in CATEGORIES.filter(c=>c.id!=='MANAGEMENT')" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>实际成本子类<select v-model="form.costCenter"><option v-for="c in ['船管／备件','船东专项','交接船','坞修','换旗','办公','人员薪资','其他']" :key="c">{{c}}</option></select></label><label class="f-checkbox"><input v-model="form.claimable" type="checkbox" :disabled="context.companyId!=='MSTS'"/>合同允许向船东收取（MSTS 承担应付）</label><div class="full f-subform"><div class="f-section-heading"><h3>混合发票按明细拆分</h3><button type="button" class="f-btn" @click="addLine">＋ 添加明细行</button></div><p class="f-small">不拆分时使用上方总额和分类；拆分后各行金额、税额须与总额相等。</p><div v-for="(l,i) in lineInputs" :key="i" class="f-invoice-line"><input v-model="l.description" :aria-label="`明细${i+1}摘要`" placeholder="明细摘要" required/><input v-model="l.amount" :aria-label="`明细${i+1}金额`" placeholder="金额" required/><select v-model="l.category" :aria-label="`明细${i+1}收费分类`"><option v-for="c in CATEGORIES.filter(c=>c.id!=='MANAGEMENT')" :key="c.id" :value="c.id">{{c.name}}</option></select><select v-model="l.costCenter" :aria-label="`明细${i+1}成本分类`"><option v-for="c in ['船管／备件','船东专项','交接船','坞修','换旗','办公','其他']" :key="c">{{c}}</option></select><label class="f-checkbox"><input v-model="l.claimable" type="checkbox"/>可收</label><input v-model="l.claimAmount" :aria-label="`明细${i+1}可收额`" placeholder="可收额（默认本行）"/><input v-model="l.tax" :aria-label="`明细${i+1}税额`" placeholder="税额"/><button type="button" class="f-icon" aria-label="删除明细" @click="lineInputs.splice(i,1)">×</button></div></div></template>
   <template v-if="['payment','receipt','loan','loanReturn','transfer','cashSpend','funding'].includes(formType)"><label>实际资金账户<select v-model="form.accountId"><option v-for="a in data.accounts.filter(a=>a.companyId===context.companyId&&a.currency===form.currency)" :key="a.id" :value="a.id">{{a.name}}</option></select></label><label v-if="['payment','receipt'].includes(formType)">银行手续费<input v-model="form.fee" inputmode="decimal" /></label><label v-if="formType==='payment'" class="f-checkbox"><input v-model="form.feeClaimable" type="checkbox" :disabled="context.companyId!=='MSTS'"/>手续费可向船东收取</label></template>
   <div v-if="formType==='receipt'" class="full f-subform"><h3>资金用途分配（独立于应收核销）</h3><p class="f-small">按净到账金额分配用途；未分配部分留待后续确认，不自动核销任何账单。</p><label v-for="c in CATEGORIES" :key="c.id" class="f-allocation"><span>{{c.name}}</span><input v-model="form['purpose_'+c.id]" :aria-label="c.name+'用途分配金额'" placeholder="0.00" inputmode="decimal"/></label></div>
   <template v-if="formType==='transfer'"><label>划入账户<select v-model="form.targetAccountId"><option v-for="a in data.accounts.filter(a=>a.companyId===context.companyId&&a.currency===form.currency&&a.id!==form.accountId)" :key="a.id" :value="a.id">{{a.name}}</option></select></label><p class="f-small full">内部划拨不确认费用；跨船代付请从付款申请选择其他应付账套。</p></template>
   <label v-if="formType==='loanReturn'">冲还借款<select v-model="form.loanId" required><option value="">请选择原借款</option><option v-for="l in eligibleLoans" :key="l.id" :value="l.id">{{l.id}} · 未还 {{format(engine.loanBalance(l.id))}}</option></select></label>
   <template v-if="formType==='asset'"><label>使用期限（月）<input v-model="form.lifeMonths" type="number" min="1" required /></label><label>残值（USD）<input v-model="form.residual" inputmode="decimal" /></label><label>折旧开始月份<input v-model="form.depreciationStart" type="month" required /></label><label>资产位置<input v-model="form.location" /></label><p class="f-small full">示例资本化门槛 {{format(data.policy.capitalThreshold)}} USD；不足门槛请录入费用。</p></template>
   <template v-if="formType==='instrument'"><label>票据类型<select v-model="form.instrumentKind"><option>申请单</option><option>支票</option><option>汇票</option></select></label><label>票据编号<input v-model="form.number" required /></label><label>到期日<input v-model="form.dueDate" type="date" /></label><p class="f-small full">票据登记及审批不改变资金。实际兑付通过付款申请记录，并将票据编号填写在摘要中。</p></template>
   <template v-if="['payment','receipt'].includes(formType)"><label v-if="formType==='payment'" class="full">核销应付账套（跨主体代付）<select v-model="form.crossCompanyId"><option v-for="c in data.companies.filter(c=>engine.role().companies.includes(c.id))" :key="c.id" :value="c.id">{{c.name}}</option></select></label><div class="full f-subform"><h3>核销明细</h3><p class="f-small">勾选同往来方、同币种单据。一笔可核销多票；收款未选择账单时登记预收，付款超出核销的部分登记预付。</p><div v-for="d in eligibleTargets" :key="d.id" class="f-allocation"><label class="f-checkbox"><input type="checkbox" :checked="allocationInputs.some(a=>a.docId===d.id)" @change="toggleAllocation(d,$event)"/><span>{{d.id}} · {{d.description}}<small>待核销 {{format(engine.outstanding(d),d.currency)}}</small></span></label><input v-if="allocationInputs.some(a=>a.docId===d.id)" v-model="allocationInputs.find(a=>a.docId===d.id).amount" :aria-label="`${d.id}核销金额`" placeholder="本次核销"/></div><p v-if="!eligibleTargets.length" class="f-empty">当前往来方、船舶、币种下没有已审核待核销单据</p></div></template>
   <div class="full f-form-footer"><span class="f-small">保存为草稿 → 提交 → 审核 → 按业务执行</span><button type="button" class="f-btn" @click="modal=''">取消</button><button class="f-btn primary" type="submit">保存草稿</button></div>
  </form>
 </FinanceDialog>

 <FinanceDialog v-if="modal==='bill'" title="生成月度船东账单" @close="modal=''"><form class="f-form" @submit.prevent="saveBill"><label class="full">管理合同<select v-model="form.contractId" required><option v-for="c in data.contracts.filter(c=>!context.vesselId||c.vesselId===context.vesselId)" :key="c.id" :value="c.id">{{vesselName(c.vesselId)}} · {{format(c.monthlyFee)}} / 月</option></select></label><label class="full f-checkbox"><input v-model="form.includeFee" type="checkbox"/>包含本月固定管理费</label><div class="f-callout full">{{context.period}}：自动提取截至本期的未出账、已审核可收发票明细，保留原费用月份。关闭固定管理费可生成补充账单；同一原票行不会重复收费。</div><div class="full f-actions"><button class="f-btn" type="button" @click="modal=''">取消</button><button class="f-btn primary">生成草稿</button></div></form></FinanceDialog>

 <FinanceDialog v-if="modal==='journal'" title="录入会计凭证" wide @close="modal=''"><form class="f-form" @submit.prevent="saveJournal"><label>记账日期<input v-model="form.date" type="date" required/></label><label>凭证摘要<input v-model="form.description" required/></label><div class="full f-subform"><div v-for="(l,i) in manualLines" :key="i" class="f-journal-line"><select v-model="l.account" :aria-label="`第${i+1}行会计科目`"><option v-for="a in data.chart.filter(a=>a.enabled)" :key="a.id" :value="a.id">{{a.id}} {{a.name}}</option></select><input v-model="l.debit" :aria-label="`第${i+1}行借方`" placeholder="借方"/><input v-model="l.credit" :aria-label="`第${i+1}行贷方`" placeholder="贷方"/><select v-model="l.cashFlow" :aria-label="`第${i+1}行现金流分类`"><option value="operating">经营活动</option><option value="investing">投资活动</option><option value="financing">筹资活动</option><option value="internal">内部划拨</option></select><button type="button" class="f-icon" aria-label="删除凭证行" @click="manualLines.splice(i,1)">×</button></div><button type="button" class="f-btn" @click="manualLines.push({account:'5602',debit:'0',credit:'0',cashFlow:'operating'})">＋ 增加分录</button></div><div class="full f-actions"><button type="button" class="f-btn" @click="modal=''">取消</button><button class="f-btn primary">保存凭证草稿</button></div></form></FinanceDialog>

 <FinanceDialog v-if="modal==='master'" :title="`${form.id?'查看／编辑':'新建'}基础档案`" @close="modal=''"><form class="f-form" @submit.prevent="saveMaster">
  <template v-if="formType==='contracts'"><label class="full">船舶<select v-model="form.vesselId"><option v-for="v in data.vessels" :key="v.id" :value="v.id">{{v.name}}</option></select></label><label>单船公司<select v-model="form.partyId"><option v-for="c in data.companies.filter(c=>c.kind==='vessel')" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>固定月费（USD）<input v-model="form.monthlyFee" required/></label><label>生效日<input v-model="form.start" type="date" required/></label><label>终止日<input v-model="form.end" type="date"/></label><label>首末月计费<select v-model="form.prorate"><option value="actual">按当月实际天数折算</option><option value="full">整月固定费</option></select></label><label>状态<select v-model="form.status"><option value="active">生效中</option><option value="inactive">停用</option></select></label></template>
  <template v-else><label class="full">名称<input v-model="form.name" required/></label><template v-if="formType==='companies'"><label>公司类型<select v-model="form.kind"><option value="management">管理公司</option><option value="vessel">单船公司</option></select></label><p class="f-small full">新账套自动创建零期初银行账户。</p></template><template v-if="formType==='parties'"><label>类型<select v-model="form.kind"><option v-for="p in ['供应商','员工','船东／客户','管理公司']" :key="p">{{p}}</option></select></label><label>部门<input v-model="form.department"/></label></template><template v-if="formType==='vessels'"><label>IMO 编号<input v-model="form.imo" required placeholder="7位真实编号或明确的示例标识"/></label><label>单船公司<select v-model="form.companyId"><option v-for="c in data.companies.filter(c=>c.kind==='vessel')" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>船东<select v-model="form.ownerId"><option v-for="p in data.parties" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>付款银行<input v-model="form.bank"/></label><label>管理开始日期<input v-model="form.start" type="date"/></label></template><template v-if="formType==='chart'"><label>科目代码<input v-model="form.id" required :disabled="Boolean(form.originalId)"/></label><label>科目性质<select v-model="form.kind"><option v-for="k in ['asset','contraAsset','liability','equity','income','expense']" :key="k" :value="k">{{kindLabel(k)}}</option></select></label><label class="f-checkbox"><input v-model="form.enabled" type="checkbox"/>启用科目</label></template><template v-if="formType==='accounts'"><label>账户类别<select v-model="form.kind"><option value="bank">银行</option><option value="cash">现金</option></select></label><label>币种<select v-model="form.currency"><option v-for="c in ['USD','CNY','HKD','EUR']" :key="c">{{c}}</option></select></label><label>示例账号<input v-model="form.number"/></label><label>船舶<select v-model="form.vesselId"><option value="">MSTS 本部</option><option v-for="v in data.vessels.filter(v=>context.companyId==='MSTS'||v.companyId===context.companyId)" :key="v.id" :value="v.id">{{v.name}}</option></select></label></template></template>
  <div class="full f-actions"><button type="button" class="f-btn" @click="modal=''">关闭</button><button class="f-btn primary" :disabled="!can('master')">保存档案</button></div></form></FinanceDialog>

 <FinanceDialog v-if="modal==='policy'" title="示例会计政策" @close="modal=''"><form class="f-form" @submit.prevent="savePolicy"><label>资本化门槛（USD）<input v-model="form.capitalThreshold" required/></label><label>资产年限（月）<input v-model="form.assetLife" type="number" min="1" required/></label><label>简单计提税率 %<input v-model="form.taxRate" type="number" min="0" max="100" step="0.01" required/></label><label>默认折旧开始<select v-model="form.depreciationStart"><option value="nextMonth">启用次月</option><option value="currentMonth">启用当月</option></select></label><p class="full f-small">仅适用于新建示例，不回写历史、已有资产卡片及已过账凭证。</p><button class="f-btn primary">保存配置</button></form></FinanceDialog>

 <FinanceDialog v-if="modal==='import'" title="银行流水导入预览" wide @close="modal=''"><div class="f-detail-body"><p>{{importFile}} · {{data.accounts.find(a=>a.id===currentBank)?.name}}</p><FinanceTable title="待导入银行流水" :rows="importRows.map((r,i)=>({...r,id:String(i)}))" :columns="[{key:'date',label:'日期'},{key:'reference',label:'外部流水号'},{key:'signedAmount',label:'收支金额',money:true,format:v=>format(v)},{key:'description',label:'摘要'}]" @select="()=>{}"/><div class="f-callout">确认导入只新增银行对账记录；重复外部流水号会跳过，不增加银行资金或重复生成凭证。</div><button class="f-btn primary" @click="confirmImport">确认导入 {{importRows.length}} 条</button></div></FinanceDialog>

 <FinanceDialog v-if="modal==='match'" title="确认银行流水匹配" @close="modal=''"><form class="f-form" @submit.prevent="saveMatch"><p class="full">银行记录 {{form.statementId}}，匹配同账户、同币种、同方向资金流水。</p><label class="full">资金台账流水<select v-model="matchMovement" required><option value="">请选择业务资金流水</option><option v-for="m in matchOptions" :key="m.id" :value="m.id">{{m.id}} · {{m.description}} · {{format(m.signedAmount)}}</option></select></label><label>本次匹配金额<input v-model="matchAmount" required/></label><button class="f-btn primary">确认匹配</button></form></FinanceDialog>

 <FinanceDialog v-if="modal==='offset'" title="报销冲员工借款" @close="modal=''"><form class="f-form" @submit.prevent="act(()=>engine.offsetLoan(selectedId,form.loanId,cents(form.amount)),'报销冲借款已记录').then(r=>{if(!dbState.error)modal=''})"><label class="full">原借款<select v-model="form.loanId" required><option value="">请选择同员工借款</option><option v-for="l in data.documents.filter(d=>d.type==='loan'&&d.companyId===context.companyId&&d.partyId===detailDoc?.partyId&&engine.loanBalance(d.id)>0)" :key="l.id" :value="l.id">{{l.id}} · 未还 {{format(engine.loanBalance(l.id))}}</option></select></label><label>本次冲借款金额<input v-model="form.amount" required/></label><button class="f-btn primary">确认冲账</button></form></FinanceDialog>

 <FinanceDialog v-if="modal==='allocate'" title="分配预收／预付余额" @close="modal=''"><form class="f-form" @submit.prevent="act(()=>engine.allocateFunds(selectedId,allocationInputs.map(a=>({docId:a.docId,amount:cents(a.amount)}))),'剩余资金已分配').then(()=>{if(!dbState.error)modal=''})"><div class="full f-allocation" v-for="d in eligibleTargets" :key="d.id"><label class="f-checkbox"><input type="checkbox" @change="toggleAllocation(d,$event)"/>{{d.id}} · {{format(engine.outstanding(d))}}</label><input v-if="allocationInputs.some(a=>a.docId===d.id)" v-model="allocationInputs.find(a=>a.docId===d.id).amount" :aria-label="`${d.id}预收预付核销额`"/></div><p v-if="!eligibleTargets.length" class="f-empty full">没有可核销余额</p><button class="f-btn primary">确认分配</button></form></FinanceDialog>

 <FinanceDialog v-if="modal==='history'" :title="`历史源行 ${form.id}`" @close="modal=''"><div class="f-detail-body"><h3>{{form.description}}</h3><dl class="f-definition"><template v-for="(value,key) in form" :key="key"><dt>{{key}}</dt><dd>{{value==null?'缺失（未推断为零）':value}}</dd></template></dl><a href="analysis-report.html" target="_blank" rel="noopener" class="f-link">打开完整工作簿及单元格溯源 ↗</a></div></FinanceDialog>

 <FinanceDialog v-if="modal==='permissions'" title="角色权限与账套范围" @close="modal=''">
  <form class="f-form" @submit.prevent="act(()=>engine.saveRole(form.roleId,form.rights,form.companies),'角色授权已保存').then(()=>{if(!dbState.error)modal=''})">
   <h3 class="full">{{ROLES.find(r=>r.id===form.roleId)?.name}}</h3>
   <label v-for="[right,label] in [['create','制单'],['submit','提交'],['review','业务审核'],['journalReview','凭证审核'],['approvePayment','付款审批'],['execute','出纳执行'],['allocate','核销'],['bank','银行对账'],['post','凭证过账'],['close','结账'],['master','基础资料'],['attach','附件'],['reset','重置演示']]" :key="right" class="f-checkbox"><input v-model="form.rights" type="checkbox" :value="right"/>{{label}}</label>
   <h3 class="full">授权账套</h3><label v-for="c in data.companies" :key="c.id" class="f-checkbox"><input v-model="form.companies" type="checkbox" :value="c.id"/>{{c.name}}</label>
   <button class="f-btn primary">保存授权</button>
  </form>
 </FinanceDialog>
</template>
